class APIFetchUtils:
    """
    Centralized API fetch utilities.
    Groups all data fetching functions for better code organization.
    All methods are static to avoid unnecessary object instantiation.
    """

    @staticmethod
    def organization_services() -> list[dict[str, Any]]:
        """
        Fetch all services defined at the organization level using the Mist API.

        Returns:
            list: List of service dictionaries with service definitions, or empty list if error

        SECURITY: Read-only operation fetching configuration data only.
        """
        try:
            org_id = ConfigUtils.get_cached_or_prompted_org_id()
            logging.info(f"Fetching organization services for org_id: {org_id}")

            # Call the Mist API to get organization services
            response = mistapi.api.v1.orgs.services.listOrgServices(apisession, org_id, limit=1000)

            if hasattr(response, "data") and response.data:
                services_data = response.data
                logging.info(f"Successfully retrieved {len(services_data)} organization services")

                # Extract service names and types for easier display
                services_list = []
                for service in services_data:
                    if isinstance(service, dict):
                        service_name = service.get("name", "unnamed")
                        service_type = service.get("type", "custom")
                        service_desc = service.get("description", "")
                        services_list.append(
                            {
                                "name": service_name,
                                "type": service_type,
                                "description": service_desc,
                                "full_config": service,  # Keep full config for reference
                            }
                        )

                return services_list

            else:
                logging.warning("No organization services found or response data is empty")
                return []

        except Exception as error:
            logging.error(f"Failed to fetch organization services: {error}")
            return []

    @staticmethod
    def all_site_settings(apisession, org_id, limit=1000):  # type: ignore[no-untyped-def]
        """
        Fetches configuration settings for all sites in the organization.

        Args:
            apisession: The Mist API session object.
            org_id: The organization ID.
            limit: (Unused) Maximum number of sites to fetch per API call.

        Returns:
            List of dictionaries, each containing the settings for a site.
        """
        logging.info("Fetching all site settings...")

        # Use mistapi.get_all to ensure pagination is handled for all sites
        sites = APICoreFetchUtils.all_sites_with_limit(org_id)

        all_configs = []
        for site in tqdm(sites, desc="Sites", unit="site"):  # type: ignore[no-untyped-call]
            if ConfigUtils.check_stop_signal():
                break
            site_id = site.get("id")
            site_name = site.get("name", "Unnamed Site")
            try:
                # Fetch the site settings using the Mist API
                config = mistapi.api.v1.sites.setting.getSiteSetting(apisession, site_id).data
                config["site_id"] = site_id
                config["site_name"] = site_name
                all_configs.append(config)
                logging.info(f"! Fetched config for site: {site_name} (ID: {site_id})")
            except Exception as error:
                logging.warning(f"! Failed to fetch config for {site_name} (ID: {site_id}): {error}")

        logging.info(f"Fetched settings for {len(all_configs)} sites.")
        return all_configs

    @staticmethod
    def gateway_device_configs(apisession, org_id, fast=False, max_workers=None):  # type: ignore[no-untyped-def]  # noqa: C901, PLR0915
        """
        Fetches configuration details for all gateway devices in the org using org inventory.
        If `fast` is True, fetches each device config concurrently using connection pool management.

        Args:
            apisession: Authenticated Mist API session.
            org_id: Organization ID.
            fast (bool): If True, enables high-concurrency mode with connection pool management.
            max_workers (int): Optional override for number of concurrent threads.

        Returns:
            List of device configuration dictionaries.
        """
        logging.info("Fetching org inventory to find gateway devices...")
        try:
            response = mistapi.api.v1.orgs.inventory.getOrgInventory(apisession, org_id, limit=1000)
            inventory = mistapi.get_all(response=response, mist_session=apisession)
        except Exception as error:
            logging.error(f"! Failed to fetch org inventory: {error}")
            return []

        logging.info(f"Found {len(inventory)} total devices in org inventory.")

        # Load site names from SiteList.csv for enrichment
        site_name_lookup = {}
        try:
            site_list_path = FilePathUtils.get_csv_path("SiteList.csv")
            with open(site_list_path, encoding="utf-8") as file_handle:
                reader = csv.DictReader(file_handle)
                site_name_lookup = {row.get("id"): row.get("name", "Unnamed Site") for row in reader}
        except Exception as error:
            logging.warning(f"! Failed to load SiteList.csv for site names: {error}")

        # Filter for gateway devices and build work list
        work_items = []
        for device in inventory:
            if device.get("type") == "gateway":
                site_id = device.get("site_id")
                device_id = device.get("id")
                if site_id and device_id:
                    site_name = site_name_lookup.get(site_id, "Unknown")
                    work_items.append((site_id, device_id, site_name))

        logging.info(f"Prepared {len(work_items)} gateway device config API calls.")

        def fetch_config(work_item, connection_semaphore):  # type: ignore[no-untyped-def]
            """Fetch configuration for a single device with retry logic."""
            work_site_id, work_device_id, work_site_name = work_item

            with connection_semaphore:  # Limit concurrent connections
                try:
                    logging.debug(f"Fetching config for {work_device_id} ({work_site_name})")
                    config_response = mistapi.api.v1.sites.devices.getSiteDevice(
                        apisession, work_site_id, work_device_id
                    )
                    config = getattr(config_response, "data", {})
                    if config:
                        # Add site metadata for enrichment
                        config["site_name"] = work_site_name
                        config["site_id"] = work_site_id
                        logging.debug(f"! Config fetched for {work_device_id}")
                        return config
                    else:
                        logging.warning(f"! Empty config for device {work_device_id}")
                except Exception as inner_error:
                    logging.error(f"! Failed to fetch config for device {work_device_id}: {inner_error}")
                    return None

        def retry_fetch_config(failed_items, connection_semaphore):  # type: ignore[no-untyped-def]
            """Retry wrapper for device config fetching."""
            max_retries = int(os.getenv("FAST_MODE_SEQUENTIAL_MAX_RETRIES", "1"))
            retry_results = []

            for failed_work_item in failed_items:
                failed_site_id, failed_device_id, failed_site_name = failed_work_item

                for attempt in range(max_retries + 1):
                    result = fetch_config(failed_work_item, connection_semaphore)  # type: ignore[no-untyped-call]
                    if result is not None:
                        retry_results.append(result)
                        break
                    if attempt < max_retries:
                        delay = 0.5 * (1.5**attempt)  # Exponential backoff
                        logging.debug(
                            f"Retrying device {failed_device_id} in {delay:.2f}s (attempt {attempt + 2}/{max_retries + 1})"  # noqa: E501
                        )
                        time.sleep(delay)
                else:
                    logging.warning(
                        f"! Failed to fetch config for device {failed_device_id} after {max_retries + 1} attempts"
                    )

            return retry_results

        # Use connection pool management helper if fast mode is enabled
        if fast:
            successful_results, failed_items = execute_with_connection_pool_management(
                work_items=work_items,
                worker_function=fetch_config,
                batch_description="gateway device configs",
                retry_function=retry_fetch_config,
            )
            all_device_configs = successful_results
        else:
            # Sequential processing for non-fast mode
            all_device_configs = []
            # Create a dummy semaphore for sequential processing
            dummy_semaphore = threading.Semaphore(1)

            for work_item in tqdm(work_items, desc="Fetching Configs", unit="device"):  # type: ignore[no-untyped-call]
                result = fetch_config(work_item, dummy_semaphore)  # type: ignore[no-untyped-call]
                if result is not None:
                    all_device_configs.append(result)

        # Filter out None results
        all_device_configs = [config for config in all_device_configs if config is not None]

        logging.info(f"! Completed fetching {len(all_device_configs)} gateway device configs.")
        return all_device_configs


# ============================================================================
# DATA PROCESSING UTILITIES CLASS
# ============================================================================


class DataProcessingUtils:
    """
    Centralized data processing utilities.
    Groups all data transformation functions for better code organization.
    All methods are static to avoid unnecessary object instantiation.

    Implementation Note: Methods contain the actual logic rather than delegating
    to standalone functions, per the 5-Item Rule class organization requirement.
    """

    @staticmethod
    def flatten_dict(d: dict[str, Any], parent_key: str = "", sep: str = "_") -> dict[str, Any]:
        """
        Recursively flattens a nested dictionary, joining keys with sep.
        Lists of dicts are flattened with indexed keys.
        Non-dict lists are joined as comma-separated strings.
        All keys are converted to strings for CSV/JSON compatibility.

        Args:
            d: Dictionary to flatten
            parent_key: Parent key prefix for nested keys
            sep: Separator for nested keys

        Returns:
            dict: Flattened dictionary
        """
        items: list[tuple[str, Any]] = []
        for k, v in d.items():
            k_str = str(k)
            new_key = f"{parent_key}{sep}{k_str}" if parent_key else k_str
            if isinstance(v, dict):
                items.extend(DataProcessingUtils.flatten_dict(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                if all(isinstance(i, dict) for i in v):
                    for idx, item in enumerate(v):
                        items.extend(DataProcessingUtils.flatten_dict(item, f"{new_key}{sep}{idx}", sep=sep).items())
                else:
                    items.append((new_key, ",".join(map(str, v))))
            else:
                items.append((new_key, v))
        return dict(items)

    @staticmethod
    def flatten_nested_fields(data: list[dict[str, Any]]) -> list[dict[str, Any]]:  # noqa: C901
        """
        Flatten nested fields in a list of dictionaries.
        Attempts to parse stringified dicts/lists.
        Recursively flattens nested dicts and lists of dicts.
        Joins non-dict lists as comma-separated strings.

        Args:
            data: List of dictionaries to process

        Returns:
            list: List of dictionaries with flattened nested fields
        """
        flattened = []
        for entry in data:
            if not isinstance(entry, dict):
                logging.debug(f"Skipping non-dictionary entry: {type(entry).__name__}")
                continue

            new_entry = {}
            for key, value in entry.items():
                # Try to parse stringified dicts/lists
                if isinstance(value, str) and (value.startswith("{") or value.startswith("[")):
                    try:
                        value = ast.literal_eval(value)
                    except Exception:
                        try:
                            value = json.loads(value)
                        except Exception:  # nosec B110
                            pass  # Leave as string if parsing fails

                if isinstance(value, dict):
                    flat = DataProcessingUtils.flatten_dict(value, parent_key=key)
                    new_entry.update(flat)
                elif isinstance(value, list):
                    if all(isinstance(i, dict) for i in value):
                        for idx, item in enumerate(value):
                            flat = DataProcessingUtils.flatten_dict(item, parent_key=f"{key}_{idx}")
                            new_entry.update(flat)
                    else:
                        new_entry[key] = ",".join(map(str, value))
                else:
                    new_entry[key] = value
            flattened.append(new_entry)
        return flattened

    @staticmethod
    def convert_list_values_to_strings(data):  # type: ignore[no-untyped-def]
        """
        Convert list, tuple, or set values to CSV-compatible comma-separated strings.

        Args:
            data: List of dictionaries containing list values

        Returns:
            Data with list values converted to strings
        """
        for entry in data:
            for key, value in entry.items():
                if isinstance(value, (list, tuple, set)):
                    logging.debug(f"Converting list/tuple/set at key '{key}' to string")
                    entry[key] = ",".join(map(str, value))
        return data

    @staticmethod
    def get_unique_keys(data):  # type: ignore[no-untyped-def]
        """
        Get all unique dictionary keys from a list of dictionaries.
        Returns a sorted list of string keys.

        Args:
            data: List of dictionaries

        Returns:
            list: Sorted list of unique keys as strings
        """
        fields = set()
        for entry in data:
            fields.update(entry.keys())
        return sorted(str(f) for f in fields)

    @staticmethod
    def escape_multiline(data):  # type: ignore[no-untyped-def]
        """
        Escape multiline strings for CSV compatibility.
        Joins list values as comma-separated strings.
        Replaces newline characters with escaped versions.

        Args:
            data: List of dictionaries containing multiline strings

        Returns:
            Data with escaped multiline strings
        """
        for entry in data:
            for key, value in entry.items():
                if isinstance(value, list):
                    entry[key] = ",".join(map(str, value))
                elif isinstance(value, str):
                    entry[key] = value.replace("\n", "\\n").replace("\r", "")
        return data


class MarvisDataUtils:
    """
    Utilities for processing Marvis AI API responses.
    Centralizes Marvis-specific data formatting for CSV export.
    All methods are static to avoid unnecessary object instantiation.
    """

    @staticmethod
    def format_for_csv(api_response_data, analysis_type="generic"):  # type: ignore[no-untyped-def]  # noqa: C901, PLR0912
        """
        Optimized formatter for Marvis API responses to create readable CSV files.

        Args:
            api_response_data: Raw API response data from Marvis troubleshoot calls
            analysis_type: Type of analysis ("client", "device", "network", "sites")

        Returns:
            List of dictionaries optimized for CSV readability
        """
        try:
            # Handle different response structures
            if not api_response_data:
                logging.warning("Empty Marvis API response received")
                return []

            # Ensure we have a list to work with
            if not isinstance(api_response_data, list):
                data_list = [api_response_data]
            else:
                data_list = api_response_data

            formatted_data = []

            for item in data_list:
                if not isinstance(item, dict):
                    logging.warning(f"Unexpected data type in Marvis response: {type(item)}")
                    continue

                # Handle organization sites SLE data specially for readability
                if analysis_type == "sites" and "results" in item and isinstance(item["results"], list):
                    logging.info(f"Processing organization sites SLE data with {len(item['results'])} sites")

                    # Create one row per site instead of flattening all sites into one massive row
                    for idx, site_data in enumerate(item["results"]):
                        site_row = {}

                        # Add metadata from parent response
                        for meta_key in ["start", "end", "limit", "page", "total"]:
                            if meta_key in item:
                                site_row[meta_key] = item[meta_key]

                        # Add site index for reference
                        site_row["site_index"] = idx

                        # Add site data with clean column names
                        if isinstance(site_data, dict):
                            for key, value in site_data.items():
                                # Use clean column names instead of results_X_key format
                                clean_key = key.replace("-", "_")  # Replace hyphens for CSV compatibility
                                site_row[clean_key] = value

                        formatted_data.append(site_row)

                    logging.info(f"Converted {len(item['results'])} sites into {len(formatted_data)} readable rows")

                else:
                    # Handle single troubleshoot results (client, device, network)
                    formatted_row = {}

                    # Add top-level metadata
                    for key, value in item.items():
                        if key == "results" and isinstance(value, list):
                            # Handle results array - flatten each result with cleaner naming
                            for idx, result in enumerate(value):
                                if isinstance(result, dict):
                                    for result_key, result_value in result.items():
                                        # Use clean column names: result_0_category instead of results_0_category
                                        clean_key = f"result_{idx}_{result_key.replace('-', '_')}"
                                        formatted_row[clean_key] = result_value
                                else:
                                    formatted_row[f"result_{idx}"] = str(result)
                        elif isinstance(value, dict):
                            # Flatten nested dicts with clean naming
                            for nested_key, nested_value in value.items():
                                clean_key = f"{key}_{nested_key}".replace("-", "_")
                                formatted_row[clean_key] = nested_value
                        elif isinstance(value, list):
                            # Join lists as comma-separated values
                            formatted_row[key] = ",".join(map(str, value))
                        else:
                            # Direct assignment for simple values
                            formatted_row[key] = value

                    if formatted_row:  # Only add if we have data
                        formatted_data.append(formatted_row)

            # Apply final CSV-friendly formatting
            formatted_data = DataProcessingUtils.escape_multiline(formatted_data)  # type: ignore[no-untyped-call]

            logging.info(f"Marvis data formatting complete: {len(formatted_data)} rows for {analysis_type} analysis")
            return formatted_data

        except Exception as error:
            logging.error(f"Error formatting Marvis data for CSV: {error}")
            # Fall back to old method if new formatting fails
            logging.info("Falling back to legacy flattening method")
            fallback_data = [api_response_data] if not isinstance(api_response_data, list) else api_response_data
            fallback_data = DataProcessingUtils.flatten_nested_fields(fallback_data)
            fallback_data = DataProcessingUtils.escape_multiline(fallback_data)  # type: ignore[no-untyped-call]
            return fallback_data


class DatabaseSchemaUtils:
    """
    Centralized database schema utilities for SQLite operations.
    Groups all schema-related functions per the 5-Item Rule class organization.
    All methods are static to avoid unnecessary object instantiation.
    """

    @staticmethod
    def determine_api_function_name_from_context() -> str:
        """
        Attempts to determine the API function name from the current call stack.
        This helps identify which endpoint strategy to use for table schema.

        Returns:
            str: The API function name if found, else 'unknown'
        """
        # Look through the call stack for known API function patterns
        frame = inspect.currentframe()
        try:
            while frame:
                function_name = frame.f_code.co_name
                # Check if this looks like an API function name
                if any(
                    pattern in function_name
                    for pattern in ["getOrg", "listOrg", "searchOrg", "getSite", "listSite", "searchSite"]
                ):
                    logging.debug(f"Detected API function name from stack: {function_name}")
                    return function_name
                frame = frame.f_back
        except Exception as error:
            logging.debug(f"Error determining API function name: {error}")
        finally:
            del frame

        return "unknown"

    @staticmethod
    def get_endpoint_strategy(api_function_name: str, data_fields: list[str]) -> dict[str, Any]:
        """
        Determines the appropriate database schema strategy for an API endpoint.

        Args:
            api_function_name (str): Name of the API function being called
            data_fields (list): List of field names in the data

        Returns:
            dict: Strategy configuration including primary key, indexes, etc.
        """
        # First check if we have a specific strategy for this endpoint
        if api_function_name in ENDPOINT_PRIMARY_KEY_STRATEGIES:
            strategy = ENDPOINT_PRIMARY_KEY_STRATEGIES[api_function_name].copy()
            logging.debug(f"Using configured strategy for {api_function_name}: {strategy['type']}")
            return strategy

        # If no specific strategy, use intelligent defaults based on data structure
        strategy: dict[str, Any] = ENDPOINT_PRIMARY_KEY_STRATEGIES["default"].copy()  # type: ignore[no-redef]

        # Enhance default strategy based on available fields
        if "id" in data_fields:
            # If data has an 'id' field, use it as unique constraint
            strategy["unique_constraints"] = ["id"]
            strategy["indexes"] = ["id"]
            logging.debug(f"Enhanced default strategy for {api_function_name}: adding unique constraint on 'id'")

        # Add common indexes for frequently queried fields
        common_index_fields = ["org_id", "site_id", "device_id", "timestamp", "mac", "serial"]
        for field_name in common_index_fields:
            if field_name in data_fields and field_name not in strategy["indexes"]:
                strategy["indexes"].append(field_name)  # type: ignore[attr-defined]

        logging.debug(f"Using enhanced default strategy for {api_function_name}: {strategy}")
        return strategy

    @staticmethod
    def build_create_table_sql(
        table_name: str,
        fields: list[str],
        strategy: dict[str, Any],
    ) -> str:  # noqa: C901, PLR0912, PLR0915
        """
        Builds the CREATE TABLE SQL statement based on the endpoint strategy.

        Args:
            table_name (str): Name of the table to create
            fields (list): List of field names from the data
            strategy (dict): Strategy configuration for this endpoint

        Returns:
            str: Complete CREATE TABLE SQL statement
        """
        datetime.now(UTC).isoformat()

        # Sanitize table name
        safe_table_name = re.sub(r"[^a-zA-Z0-9_]", "_", table_name)
        if not safe_table_name or safe_table_name[0].isdigit():
            safe_table_name = f"table_{safe_table_name}"

        # Start building SQL
        if strategy["type"] == "natural_pk":
            # Use API id field(s) as primary key
            pk_fields = strategy["primary_key"]
            sql_parts = [f"CREATE TABLE IF NOT EXISTS {safe_table_name} ("]

            # Add all fields, with primary key fields getting special treatment
            field_definitions = []
            for field in fields:
                safe_field = re.sub(r"[^a-zA-Z0-9_]", "_", str(field))
                if field in pk_fields:
                    field_definitions.append(f"{safe_field} TEXT NOT NULL")
                else:
                    field_definitions.append(f"{safe_field} TEXT")

            # Add metadata fields
            field_definitions.append("misthelper_created_time TEXT DEFAULT CURRENT_TIMESTAMP")
            field_definitions.append("misthelper_updated_time TEXT DEFAULT CURRENT_TIMESTAMP")

            sql_parts.append(", ".join(field_definitions))

            # Add primary key constraint
            pk_constraint = f"PRIMARY KEY ({', '.join(pk_fields)})"
            sql_parts.append(f", {pk_constraint}")

            sql_parts.append(")")
            create_sql = "".join(sql_parts)

        elif strategy["type"] == "composite_pk":
            # Use composite primary key
            pk_fields = strategy["primary_key"]
            sql_parts = [f"CREATE TABLE IF NOT EXISTS {safe_table_name} ("]

            field_definitions = []
            for field in fields:
                safe_field = re.sub(r"[^a-zA-Z0-9_]", "_", str(field))
                if field in pk_fields:
                    field_definitions.append(f"{safe_field} TEXT NOT NULL")
                else:
                    field_definitions.append(f"{safe_field} TEXT")

            # Add metadata fields
            field_definitions.append("misthelper_created_time TEXT DEFAULT CURRENT_TIMESTAMP")
            field_definitions.append("misthelper_updated_time TEXT DEFAULT CURRENT_TIMESTAMP")

            sql_parts.append(", ".join(field_definitions))

            # Add composite primary key constraint
            available_pk_fields = [f for f in pk_fields if f in fields]
            if available_pk_fields:
                pk_constraint = f"PRIMARY KEY ({', '.join(available_pk_fields)})"
                sql_parts.append(f", {pk_constraint}")

            sql_parts.append(")")
            create_sql = "".join(sql_parts)

        else:  # auto_increment_with_unique
            # Use auto-increment primary key with unique constraints
            sql_parts = [f"CREATE TABLE IF NOT EXISTS {safe_table_name} ("]

            field_definitions = ["misthelper_internal_id INTEGER PRIMARY KEY AUTOINCREMENT"]

            for field in fields:
                safe_field = re.sub(r"[^a-zA-Z0-9_]", "_", str(field))
                field_definitions.append(f"{safe_field} TEXT")

            # Add metadata fields
            field_definitions.append("misthelper_created_time TEXT DEFAULT CURRENT_TIMESTAMP")
            field_definitions.append("misthelper_updated_time TEXT DEFAULT CURRENT_TIMESTAMP")

            sql_parts.append(", ".join(field_definitions))

            # Add unique constraints if specified
            unique_fields = [f for f in strategy["unique_constraints"] if f in fields]
            if unique_fields:
                for field in unique_fields:
                    safe_field = re.sub(r"[^a-zA-Z0-9_]", "_", str(field))
                    sql_parts.append(f", UNIQUE({safe_field})")

            sql_parts.append(")")
            create_sql = "".join(sql_parts)

        logging.debug(f"Generated CREATE TABLE SQL for {safe_table_name}: {create_sql[:100]}...")
        return create_sql

    @staticmethod
    def build_indexes_sql(table_name: str, fields: list[str], strategy: dict[str, Any]) -> list[str]:
        """
        Builds CREATE INDEX SQL statements for the specified strategy.

        Args:
            table_name (str): Name of the table
            fields (list): Available fields in the data
            strategy (dict): Strategy configuration

        Returns:
            list: List of CREATE INDEX SQL statements
        """
        safe_table_name = re.sub(r"[^a-zA-Z0-9_]", "_", table_name)
        if not safe_table_name or safe_table_name[0].isdigit():
            safe_table_name = f"table_{safe_table_name}"

        index_sqls = []

        # Create indexes for fields specified in strategy
        for field_name in strategy.get("indexes", []):
            if field_name in fields:
                safe_field = re.sub(r"[^a-zA-Z0-9_]", "_", str(field_name))
                index_name = f"idx_{safe_table_name}_{safe_field}"
                index_sql = f"CREATE INDEX IF NOT EXISTS {index_name} ON {safe_table_name} ({safe_field})"
                index_sqls.append(index_sql)

        return index_sqls


class SQLiteDatabaseWriter:
    """
    Write list of dictionaries to SQLite database using hybrid primary key strategies.

    Eliminates artificial api_id fields and uses proper business keys from Mist API.
    Follows NASA/JPL coding standards with comprehensive logging and error handling.

    SECURITY: Parameterized queries prevent SQL injection

    Usage:
        SQLiteDatabaseWriter(data, table_name, api_function_name).write()
    """

    def __init__(self, data: list[dict[str, Any]], table_name: str, api_function_name: str | None = None):
        """Initialize writer with data, table name, and optional API function name."""
        self.data = data
        self.table_name = table_name
        self.api_function_name = api_function_name
        self.timestamp = datetime.now(UTC).isoformat()
        self.processed_data: list[dict[str, Any]] = []
        self.fields: list[str] = []
        self.strategy: dict[str, Any] = {}
        self.connection: sqlite3.Connection | None = None
        self.cursor: sqlite3.Cursor | None = None

    def write(self) -> bool:
        """Main entry point - orchestrates the database write operation."""
        self._log_entry()
        if not self._validate_inputs():
            return False
        self._resolve_api_function_name()
        if not self._ensure_database_directory():
            return False
        if not self._process_data():
            return False
        if not self._determine_fields_and_strategy():
            return False
        return self._execute_database_operations()

    def _log_entry(self) -> None:
        """Log entry point with input parameters."""
        row_count = len(self.data) if self.data else 0
        logging.debug(
            f"ENTRY: SQLiteDatabaseWriter.write(data_rows={row_count}, table_name={self.table_name}, api_function_name={self.api_function_name}) at {self.timestamp}"  # noqa: E501
        )

    def _validate_inputs(self) -> bool:
        """Validate data and table name inputs."""
        if not self._validate_data():
            return False
        return self._validate_table_name()

    def _validate_data(self) -> bool:
        """Validate that data is a non-empty list."""
        if not self.data:
            logging.warning(f"No data provided to write to table {self.table_name} at {self.timestamp}")
            logging.debug("EXIT: SQLiteDatabaseWriter.write - no data to write")
            return False
        if not isinstance(self.data, list):
            logging.error(f"Invalid data type: expected list, got {type(self.data)} at {self.timestamp}")
            logging.debug("EXIT: SQLiteDatabaseWriter.write - invalid data type")
            return False
        return True

    def _validate_table_name(self) -> bool:
        """Validate that table name is a non-empty string."""
        if not self.table_name or not isinstance(self.table_name, str):
            logging.error(f"Invalid table name: {self.table_name} at {self.timestamp}")
            logging.debug("EXIT: SQLiteDatabaseWriter.write - invalid table name")
            return False
        return True

    def _resolve_api_function_name(self) -> None:
        """Determine API function name from context if not provided."""
        if not self.api_function_name:
            self.api_function_name = DatabaseSchemaUtils.determine_api_function_name_from_context()
        logging.debug(
            f"Processing {len(self.data)} rows for table {self.table_name} using API function {self.api_function_name} at {self.timestamp}"  # noqa: E501
        )

    def _ensure_database_directory(self) -> bool:
        """Create database directory if it does not exist."""
        db_dir = os.path.dirname(DATABASE_PATH)
        if not db_dir or os.path.exists(db_dir):
            return True
        try:
            os.makedirs(db_dir, exist_ok=True)
            logging.info(f"Created database directory: {db_dir} at {self.timestamp}")
            return True
        except OSError as error:
            logging.error(f"Failed to create database directory {db_dir}: {error} at {self.timestamp}")
            logging.debug("EXIT: SQLiteDatabaseWriter.write - directory creation failed")
            return False

    def _process_data(self) -> bool:
        """Process data to handle formatting for database storage."""
        try:
            self.processed_data = DataProcessingUtils.escape_multiline(self.data)  # type: ignore[no-untyped-call]
            logging.debug(f"Successfully processed data for SQLite compatibility at {self.timestamp}")
            return True
        except Exception as error:
            logging.error(f"Failed to process data: {error} at {self.timestamp}")
            logging.debug("EXIT: SQLiteDatabaseWriter.write - data processing failed")
            return False

    def _determine_fields_and_strategy(self) -> bool:
        """Get all unique fields and determine primary key strategy."""
        try:
            self.fields = DataProcessingUtils.get_unique_keys(self.processed_data)  # type: ignore[no-untyped-call]
            if not self.fields:
                logging.error(f"No fields found in data for table {self.table_name} at {self.timestamp}")
                logging.debug("EXIT: SQLiteDatabaseWriter.write - no fields")
                return False
            api_func_name = self.api_function_name if self.api_function_name else ""
            self.strategy = DatabaseSchemaUtils.get_endpoint_strategy(api_func_name, self.fields)
            self._log_strategy_info()
            return True
        except Exception as error:
            logging.error(f"Failed to determine fields and strategy: {error} at {self.timestamp}")
            logging.debug("EXIT: SQLiteDatabaseWriter.write - field determination failed")
            return False

    def _log_strategy_info(self) -> None:
        """Log strategy selection details."""
        logging.info(
            f"Using hybrid SQLite strategy '{self.strategy['type']}' for table {self.table_name}: {self.strategy['description']}"  # noqa: E501
        )
        logging.debug(f"Database fields determined: {self.fields} at {self.timestamp}")
        logging.debug(
            f"Endpoint {self.api_function_name} mapped to {self.strategy['type']} strategy - eliminates need for artificial api_id fields"  # noqa: E501
        )

    def _execute_database_operations(self) -> bool:
        """Execute database operations with comprehensive error handling."""
        try:
            self._connect_to_database()
            self._create_table_and_indexes()
            insert_mode = self._determine_insert_mode()
            safe_fields = self._prepare_safe_fields()
            successful_inserts = self._insert_all_rows(insert_mode, safe_fields)
            self._commit_and_verify(successful_inserts)
            logging.debug("EXIT: SQLiteDatabaseWriter.write - success")
            return True
        except sqlite3.Error as error:
            self._handle_sqlite_error(error)
            return False
        except Exception as error:
            self._handle_unexpected_error(error)
            return False
        finally:
            self._close_connection()

    def _connect_to_database(self) -> None:
        """Connect to SQLite database."""
        logging.debug(f"Attempting to connect to database: {DATABASE_PATH} at {self.timestamp}")
        self.connection = sqlite3.connect(DATABASE_PATH)
        self.cursor = self.connection.cursor()
        logging.info(f"Successfully connected to database: {DATABASE_PATH} at {self.timestamp}")

    def _create_table_and_indexes(self) -> None:
        """Create table with strategy-appropriate schema and indexes."""
        assert self.cursor is not None, "Database cursor not initialized"  # nosec B101
        create_table_sql = DatabaseSchemaUtils.build_create_table_sql(self.table_name, self.fields, self.strategy)
        self.cursor.execute(create_table_sql)
        logging.debug(
            f"Table {self.table_name} created/verified with hybrid {self.strategy['type']} schema - using natural business keys from API"  # noqa: E501
        )
        index_sqls = DatabaseSchemaUtils.build_indexes_sql(self.table_name, self.fields, self.strategy)
        for index_sql in index_sqls:
            self.cursor.execute(index_sql)
        if index_sqls:
            logging.debug(
                f"Created {len(index_sqls)} performance indexes for table {self.table_name} with {self.strategy['type']} strategy"  # noqa: E501
            )

    def _determine_insert_mode(self) -> str:
        """Determine insert strategy based on schema type."""
        assert self.cursor is not None, "Database cursor not initialized"  # nosec B101
        if self.strategy["type"] in ["natural_pk", "composite_pk"]:
            logging.debug(
                f"Using REPLACE mode for {self.strategy['type']} strategy - enables efficient upsert operations with natural keys"  # noqa: E501
            )
            return "INSERT OR REPLACE"
        safe_table = self._get_safe_table_name()
        self.cursor.execute(f"DELETE FROM {safe_table}")  # nosec B608
        logging.debug("Cleared existing data and using INSERT mode for auto-increment fallback strategy")
        return "INSERT"

    def _get_safe_table_name(self) -> str:
        """Get sanitized table name safe for SQL."""
        safe_table_name = re.sub(r"[^a-zA-Z0-9_]", "_", self.table_name)
        if not safe_table_name or safe_table_name[0].isdigit():
            safe_table_name = f"table_{safe_table_name}"
        return safe_table_name

    def _prepare_safe_fields(self) -> list[str]:
        """Prepare sanitized field names with metadata columns."""
        safe_fields = [re.sub(r"[^a-zA-Z0-9_]", "_", str(field)) for field in self.fields]
        safe_fields.extend(["misthelper_created_time", "misthelper_updated_time"])
        return safe_fields

    def _insert_all_rows(self, insert_mode: str, safe_fields: list[str]) -> int:
        """Insert all data rows and return count of successful inserts."""
        current_time = datetime.now(UTC).isoformat()
        successful_inserts = 0
        for idx, row in enumerate(self.processed_data):
            if self._insert_single_row(idx, row, insert_mode, safe_fields, current_time):
                successful_inserts += 1
        return successful_inserts

    def _insert_single_row(
        self, idx: int, row: dict[str, Any], insert_mode: str, safe_fields: list[str], current_time: str
    ) -> bool:
        """Insert a single row into the database."""
        assert self.cursor is not None, "Database cursor not initialized"  # nosec B101
        try:
            values = self._prepare_row_values(row, current_time)
            insert_sql = self._build_insert_sql(insert_mode, safe_fields, len(values))
            self.cursor.execute(insert_sql, values)
            if idx < 3:
                logging.debug(f"Row {idx} inserted into {self.table_name} using {insert_mode} at {self.timestamp}")
            return True
        except Exception as error:
            logging.error(f"Failed to insert row {idx} into {self.table_name}: {error} at {self.timestamp}")
            return False

    def _prepare_row_values(self, row: dict[str, Any], current_time: str) -> list[str]:
        """Prepare values for a single row including metadata."""
        values = []
        for field_name in self.fields:
            value = row.get(field_name, "")
            values.append("" if value is None else str(value))
        values.extend([current_time, current_time])
        return values

    def _build_insert_sql(self, insert_mode: str, safe_fields: list[str], value_count: int) -> str:
        """Build parameterized INSERT SQL statement."""
        placeholders = ", ".join(["?"] * value_count)
        safe_table_name = self._get_safe_table_name()
        return f"{insert_mode} INTO {safe_table_name} ({', '.join(safe_fields)}) VALUES ({placeholders})"

    def _commit_and_verify(self, successful_inserts: int) -> None:
        """Commit transaction and verify row count."""
        assert self.connection is not None, "Database connection not initialized"  # nosec B101
        assert self.cursor is not None, "Database cursor not initialized"  # nosec B101
        self.connection.commit()
        logging.info(
            f"Successfully wrote {successful_inserts}/{len(self.processed_data)} rows to table {self.table_name} in database {DATABASE_PATH} using {self.strategy['type']} strategy at {self.timestamp}"  # noqa: E501
        )
        safe_table_name = self._get_safe_table_name()
        self.cursor.execute(f"SELECT COUNT(*) FROM {safe_table_name}")  # nosec B608
        row_count = self.cursor.fetchone()[0]
        logging.info(
            f"Database verification: {row_count} rows confirmed in table {self.table_name} at {self.timestamp}"
        )

    def _handle_sqlite_error(self, error: sqlite3.Error) -> None:
        """Handle SQLite-specific errors with rollback."""
        logging.error(f"SQLite error when writing to {self.table_name}: {error} at {self.timestamp}")
        self._rollback_transaction()
        logging.debug("EXIT: SQLiteDatabaseWriter.write - SQLite error")

    def _handle_unexpected_error(self, error: Exception) -> None:
        """Handle unexpected errors with rollback."""
        logging.error(f"Unexpected error when writing to table {self.table_name}: {error} at {self.timestamp}")
        self._rollback_transaction()
        logging.debug("EXIT: SQLiteDatabaseWriter.write - unexpected error")

    def _rollback_transaction(self) -> None:
        """Rollback transaction if connection exists."""
        if not self.connection:
            return
        try:
            self.connection.rollback()
            logging.debug(f"Transaction rolled back for table {self.table_name} at {self.timestamp}")
        except Exception as rollback_error:
            logging.error(f"Failed to rollback transaction: {rollback_error} at {self.timestamp}")

    def _close_connection(self) -> None:
        """Close database connection (safety-critical: resource cleanup)."""
        if not self.connection:
            return
        try:
            self.connection.close()
            logging.debug(f"Database connection closed for table {self.table_name} at {self.timestamp}")
        except Exception as error:
            logging.error(f"Failed to close database connection: {error} at {self.timestamp}")


class DataExporter:
    """
    Handles data export operations for CSV and Redis/SQLite output formats.
    Centralizes all data saving logic that was previously scattered across functions.
    Uses static methods to avoid unnecessary object instantiation.
    """

    @staticmethod
    def write_with_format_selection(
        data: list[dict[str, Any]],
        filename_or_table: str,
        format_override: str | None = None,
        api_function_name: str | None = None,
    ) -> bool:
        """
        Writes data to either CSV or SQLite database based on global OUTPUT_FORMAT or override.

        Args:
            data: List of dictionaries containing the data to write
            filename_or_table: CSV filename or database table name
            format_override: Optional override for output format ("csv" or "sqlite")
            api_function_name: Name of the API function for SQLite strategy selection

        Returns:
            bool: True if successful, False otherwise
        """
        output_format = format_override if format_override else OUTPUT_FORMAT
        logging.debug(
            f"DataExporter.write_with_format_selection: rows={len(data) if data else 0}, target={filename_or_table}, format={output_format}, api_func={api_function_name}"  # noqa: E501
        )

        if not DataExporter._validate_write_inputs(data, filename_or_table, output_format):
            return False

        try:
            if output_format == "csv":
                return DataExporter._write_csv_format(data, filename_or_table)
            else:
                return DataExporter._write_sqlite_format(data, filename_or_table, api_function_name)
        except Exception as error:
            logging.error(f"Failed to write data to {filename_or_table} in {output_format} format: {error}")
            return False

    @staticmethod
    def _validate_write_inputs(data: list[dict[str, Any]], filename_or_table: str, output_format: str) -> bool:
        """Validate inputs for write operation. Returns True if valid."""
        if not data:
            logging.warning(f"No data provided for output to {filename_or_table}")
            return False

        if output_format not in ["csv", "sqlite"]:
            logging.error(f"Invalid output format: {output_format}. Must be 'csv' or 'sqlite'")
            return False

        return True

    @staticmethod
    def _write_csv_format(data: list[dict[str, Any]], filename_or_table: str) -> bool:
        """Write data to CSV format. Returns True on success."""
        csv_filename = filename_or_table if filename_or_table.endswith(".csv") else f"{filename_or_table}.csv"
        logging.info(f"Writing {len(data)} rows to CSV file: {csv_filename}")
        DataExporter.write_to_csv(data, csv_filename)
        return True

    @staticmethod
    def _write_sqlite_format(data: list[dict[str, Any]], filename_or_table: str, api_function_name: str | None) -> bool:
        """Write data to SQLite format. Returns True on success."""
        table_name = filename_or_table[:-4] if filename_or_table.endswith(".csv") else filename_or_table
        logging.debug(f"SQLite write: table={table_name}, api_function={api_function_name}, strategy lookup initiated")
        logging.info(f"Writing {len(data)} rows to SQLite table: {table_name}")
        return SQLiteDatabaseWriter(data, table_name, api_function_name).write()

    @staticmethod
    def write_to_csv(data: list[dict[str, Any]], csv_file: str) -> None:
        """
        Writes a list of dictionaries to a CSV file.
        - Escapes multiline strings for CSV compatibility.
        - Determines all unique fields for the CSV header.
        - Writes each row, filling missing fields with empty strings.
        - Uses data directory for container persistence.
        """
        logging.debug(f"ENTRY: DataExporter.write_to_csv(data_rows={len(data) if data else 0}, csv_file={csv_file})")

        if not data:
            logging.warning(f"No data provided to write to {csv_file}")
            logging.debug("EXIT: DataExporter.write_to_csv - no data to write")
            return

        # Ensure data directory exists and construct proper file path
        data_dir = "data"
        os.makedirs(data_dir, exist_ok=True)

        # If csv_file doesn't already include a path, place it in the data directory
        if not os.path.dirname(csv_file):
            csv_file_path = os.path.join(data_dir, csv_file)
        else:
            csv_file_path = csv_file

        logging.debug(f"Preparing to write {len(data)} rows to {csv_file_path}...")
        escaped_data = DataProcessingUtils.escape_multiline(data)  # type: ignore[no-untyped-call]
        fields = DataProcessingUtils.get_unique_keys(escaped_data)  # type: ignore[no-untyped-call]
        logging.debug(f"CSV fields determined: {fields}")

        try:
            logging.debug(f"File I/O: Attempting to open {csv_file_path} for writing")
            with open(csv_file_path, "w", newline="", encoding="utf-8") as file_handle:
                writer = csv.DictWriter(file_handle, fieldnames=fields)
                writer.writeheader()
                logging.debug(f"File I/O: Successfully wrote CSV header to {csv_file_path}")

                for idx, row in enumerate(escaped_data):
                    writer.writerow({field: row.get(field, "") for field in fields})
                    if idx < 3:  # Log the first few rows for debugging
                        logging.debug(f"Row {idx} written: {row}")

            logging.info(f"File I/O: Successfully wrote {len(escaped_data)} rows to {csv_file_path}")
            logging.debug("EXIT: DataExporter.write_to_csv - success")

        except PermissionError as perm_error:
            logging.error(f"File I/O: Permission denied when writing to {csv_file_path}: {perm_error}")
            print(f"! Cannot write to {csv_file_path}. Is it open in another program?")
            logging.debug("EXIT: DataExporter.write_to_csv - permission error")
            raise
        except OSError as os_error:
            logging.error(f"File I/O: OS error when writing to {csv_file_path}: {os_error}")
            logging.debug("EXIT: DataExporter.write_to_csv - OS error")
            raise
        except Exception as unexpected_error:
            logging.error(f"File I/O: Unexpected error when writing to {csv_file}: {unexpected_error}")
            logging.debug("EXIT: DataExporter.write_to_csv - unexpected error")
            raise

    @staticmethod
    def save_data_to_output(data, filename, api_function_name=None):  # type: ignore[no-untyped-def]
        """
        Save data to the specified format (CSV or SQLite).
        Convenience method with identical signature for backward compatibility.

        Args:
            data: List of dictionaries containing the data to write
            filename: CSV filename or database table name
            api_function_name: Name of the API function for SQLite strategy selection

        Returns:
            bool: True if successful, False otherwise
        """
        return DataExporter.write_with_format_selection(data, filename, api_function_name=api_function_name)

    @staticmethod
    def export_with_processing(data, filename, sort_key=None, api_function_name=None):  # type: ignore[no-untyped-def]
        """
        Export data with standard processing (flatten, escape, sort).
        Common pattern used throughout the codebase.

        Args:
            data (list): Raw data from API
            filename (str): Output filename
            sort_key (str, optional): Key to sort by
            api_function_name (str, optional): API function name for strategy

        Returns:
            int: Number of records processed
        """
        if not data:
            logging.warning(f"No data to export for {filename}")
            return 0

        # Filter to dict entries only (defensive)
        processed_data = [entry for entry in data if isinstance(entry, dict)]

        # Sort if requested
        if sort_key:
            processed_data = sorted(processed_data, key=lambda x: x.get(sort_key, ""))
            logging.debug(f"Data sorted by key: {sort_key}")

        # Apply standard processing
        processed_data = DataProcessingUtils.flatten_nested_fields(processed_data)
        processed_data = DataProcessingUtils.escape_multiline(processed_data)  # type: ignore[no-untyped-call]

        # Save the processed data
        success = DataExporter.save_data_to_output(processed_data, filename, api_function_name)  # type: ignore[no-untyped-call]

        if success:
            logging.info(f"Exported {len(processed_data)} records to {filename}")
            return len(processed_data)
        else:
            logging.error(f"Failed to export data to {filename}")
            return 0


class APIDataFetcher:
    """
    Fetches data from Mist API, processes it, and exports to CSV/SQLite.

    Handles API rate limiting, malformed responses, and provides emergency
    data saves on errors. Displays results in PrettyTable for logging.

    Safety Features:
        - Emergency data saves on any exception
        - Handles HTTP 429 rate limiting gracefully
        - Recovers data from malformed API responses
        - Detailed logging for troubleshooting
    """

    def __init__(  # type: ignore[no-untyped-def]
        self,
        title: str,
        api_call: Any,
        filename: str,
        sort_key: str | None = None,
        display_fields: list[str] | None = None,
        **kwargs,
    ):
        """
        Initialize the API data fetcher.

        Args:
            title: Display title for the operation
            api_call: Mist API function to call
            filename: Output filename (without extension)
            sort_key: Optional field to sort results by
            display_fields: Optional list of fields for table display
            **kwargs: Additional arguments passed to the API call
        """
        self.title = title
        self.api_call = api_call
        self.filename = filename
        self.sort_key = sort_key
        self.display_fields = display_fields
        self.kwargs = kwargs

        self.org_id = ""
        self.rawdata: list[dict[str, Any]] = []
        self.smoothed: float | None = None

    def execute(self) -> None:
        """Execute the complete API fetch workflow."""
        self._log_entry()
        self.org_id = ConfigUtils.get_cached_or_prompted_org_id()

        try:
            self._fetch_api_data()

            if self.rawdata is None or len(self.rawdata) == 0:
                logging.warning(f"! No data returned from API for {self.title}. Skipping.")
                logging.debug("EXIT: APIDataFetcher.execute - no data")
                return

            self._export_and_display_data()
            logging.debug("EXIT: APIDataFetcher.execute - success")

        except Exception as error:
            self._handle_outer_exception(error)
            raise

    # =========================================================================
    # INITIALIZATION AND LOGGING METHODS
    # =========================================================================

    def _log_entry(self) -> None:
        """Log entry point with parameters."""
        api_name = self.api_call.__name__
        logging.debug(
            f"ENTRY: APIDataFetcher(title={self.title}, api_call={api_name}, "
            f"filename={self.filename}, sort_key={self.sort_key}, kwargs={self.kwargs})"
        )
        logging.info(f"Starting data fetch: {self.title}")
        print(self.title)

    # =========================================================================
    # API CALL METHODS
    # =========================================================================

    def _fetch_api_data(self) -> None:
        """Make API call and retrieve paginated results with retry on timeout."""
        api_name = self.api_call.__name__
        logging.debug(f"Making API call: {api_name} with kwargs: {self.kwargs}")

        response = self._call_api_with_retry(api_name)
        self._apply_rate_limiting()
        self._log_response_structure(response)

        try:
            self.rawdata = mistapi.get_all(response=response, mist_session=apisession)
            record_count = len(self.rawdata) if self.rawdata else 0
            logging.debug(f"API call successful, retrieved {record_count} raw records")
        except KeyError as error:
            self._handle_key_error(response, error)
        except Exception as error:
            self._handle_api_exception(error)

    def _call_api_with_retry(self, api_name: str) -> Any:
        """Call API with retry logic for timeout and connection errors.

        Detects failures by checking response.status_code (None when mistapi
        swallows a timeout/connection exception). Retries up to
        API_REQUEST_MAX_RETRIES times with exponential backoff.

        Args:
            api_name: Name of the API function for logging.

        Returns:
            The API response object.
        """
        last_response = None
        for attempt in range(API_REQUEST_MAX_RETRIES + 1):
            response = self.api_call(apisession, self.org_id, **self.kwargs)
            last_response = response

            if self._is_response_valid(response):
                return response

            if attempt < API_REQUEST_MAX_RETRIES:
                delay = API_REQUEST_RETRY_DELAY * (2**attempt)
                logging.warning(
                    f"API call {api_name} failed (attempt {attempt + 1}/{API_REQUEST_MAX_RETRIES + 1}) "
                    f"- retrying in {delay:.0f}s"
                )
                print(
                    f"! API call timed out - retrying in {delay:.0f}s (attempt {attempt + 2}/{API_REQUEST_MAX_RETRIES + 1})"  # noqa: E501
                )
                time.sleep(delay)

        logging.error(f"API call {api_name} failed after {API_REQUEST_MAX_RETRIES + 1} attempts")
        return last_response

    @staticmethod
    def _is_response_valid(response: Any) -> bool:
        """Check if an API response indicates a successful call.

        Returns False when status_code is None (timeout/connection error
        swallowed by mistapi) or when it indicates a server error.
        """
        status = getattr(response, "status_code", None)
        if status is None:
            return False
        if status >= 500:
            return False
        return True

    def _apply_rate_limiting(self) -> None:
        """Apply rate limiting delay between API calls."""
        self.smoothed, delay = RateLimitingUtils.get_rate_limited_delay(self.smoothed)  # type: ignore[no-untyped-call]
        logging.debug(f"Applying rate limit delay: {delay:.2f}s")
        time.sleep(delay)

    def _log_response_structure(self, response: Any) -> None:
        """Log API response structure for debugging."""
        logging.debug(f"API response type: {type(response)}")
        if not hasattr(response, "data"):
            return

        logging.debug(f"Response.data type: {type(response.data)}")
        if isinstance(response.data, dict):
            logging.debug(f"Response.data keys: {list(response.data.keys())}")
        elif isinstance(response.data, list):
            logging.debug(f"Response.data is list with {len(response.data)} items")

    # =========================================================================
    # ERROR HANDLING METHODS
    # =========================================================================

    def _handle_key_error(self, response: Any, error: KeyError) -> None:
        """Handle missing 'results' key or other structure issues."""
        logging.error(f"API response structure error - missing key: {error}")
        self._log_response_error_details(response)

        recovered_data = self._attempt_data_recovery(response)

        if recovered_data:
            self.rawdata = recovered_data
            self._save_recovered_data()
        else:
            self._handle_no_recovery()

    def _log_response_error_details(self, response: Any) -> None:
        """Log detailed response information during error handling."""
        has_data = hasattr(response, "data")
        logging.error(f"Response details: type={type(response)}, hasattr(data)={has_data}")

        if has_data:
            logging.error(f"Response.data type={type(response.data)}")
            if isinstance(response.data, dict):
                logging.error(f"Available keys: {list(response.data.keys())}")

    def _attempt_data_recovery(self, response: Any) -> list[dict[str, Any]] | None:
        """Attempt to recover data from alternate response structures."""
        if not hasattr(response, "data"):
            return None

        if isinstance(response.data, dict):
            if "data" in response.data:
                recovered = response.data.get("data", [])
                logging.info(f"Recovered {len(recovered)} records from response.data['data']")
                return recovered  # type: ignore[no-any-return]

        if isinstance(response.data, list):
            logging.info(f"Recovered {len(response.data)} records from response.data (list)")
            return response.data

        return None

    def _save_recovered_data(self) -> None:
        """Save recovered data and notify user."""
        print(f"! API returned unexpected structure. Recovered {len(self.rawdata)} records.")
        api_name = self.api_call.__name__
        DataExporter.save_data_to_output(self.rawdata, self.filename, api_function_name=api_name)  # type: ignore[no-untyped-call]
        logging.info(f"Recovered data saved to {self.filename} ({len(self.rawdata)} rows)")

    def _handle_no_recovery(self) -> None:
        """Handle case where no data could be recovered."""
        print("! API response missing expected 'results' key. No data could be recovered.")
        logging.error(f"Unable to recover any data from malformed response for {self.title}")
        logging.debug("EXIT: APIDataFetcher - structure error, no recovery")

    def _handle_api_exception(self, error: Exception) -> None:
        """Handle exceptions during API data retrieval."""
        logging.error(f"Exception occurred during API data retrieval: {error}")
        logging.error(f"Exception type: {type(error).__name__}")
        print(f"! Exception occurred during API call: {error}")

        if self._is_rate_limit_error(error):
            self._handle_rate_limit()
            return

        self._emergency_save_and_raise(error)

    def _is_rate_limit_error(self, error: Exception) -> bool:
        """Check if exception is HTTP 429 rate limit error."""
        status_code = getattr(getattr(error, "response", None), "status_code", None)
        return status_code == 429

    def _handle_rate_limit(self) -> None:
        """Handle HTTP 429 rate limit error."""
        logging.warning("API rate limit (HTTP 429) reached. Saving partial results and exiting.")

        if self.rawdata:
            api_name = self.api_call.__name__
            DataExporter.save_data_to_output(self.rawdata, self.filename, api_function_name=api_name)  # type: ignore[no-untyped-call]
            logging.info(f"Partial results saved to {self.filename} ({len(self.rawdata)} rows)")
            print(f"* Partial data saved: {len(self.rawdata)} records written to {self.filename}")

        logging.debug("EXIT: APIDataFetcher - rate limited")

    def _emergency_save_and_raise(self, error: Exception) -> None:
        """Save partial data before re-raising exception."""
        if self.rawdata:
            try:
                api_name = self.api_call.__name__
                DataExporter.save_data_to_output(self.rawdata, self.filename, api_function_name=api_name)  # type: ignore[no-untyped-call]
                logging.info(f"Emergency save: {len(self.rawdata)} partial records saved before error exit")
                print(f"* Emergency save: {len(self.rawdata)} partial records written to {self.filename}")
            except Exception as save_error:
                logging.error(f"Failed to save partial data during error handling: {save_error}")

        logging.debug("EXIT: APIDataFetcher - API error")
        raise error

    def _handle_outer_exception(self, error: Exception) -> None:
        """Handle exceptions at the top level."""
        logging.error(f"! Error during data fetch for {self.title}: {error}")
        logging.error(f"Exception type: {type(error).__name__}, Traceback info available in logs")

        if self.rawdata:
            self._save_partial_data_on_error(error)
        else:
            print("! No data was collected before the error occurred")

        logging.debug("EXIT: APIDataFetcher - error")

    def _save_partial_data_on_error(self, error: Exception) -> None:
        """Save partial data when outer exception occurs."""
        try:
            api_name = self.api_call.__name__
            DataExporter.save_data_to_output(self.rawdata, self.filename, api_function_name=api_name)  # type: ignore[no-untyped-call]
            logging.info(f"Partial results saved to {self.filename} ({len(self.rawdata)} rows)")

            print("\n!! PARTIAL DATA SAVED !!")
            print(f"   * Despite the error, {len(self.rawdata)} records were successfully saved to {self.filename}")
            print(f"   * Error: {str(error)}")
            print("   * You can retry the operation later to get remaining data")
        except Exception as save_error:
            logging.error(f"Failed to save partial data in outer exception handler: {save_error}")
            print(f"! Critical: Could not save partial data. Error: {save_error}")

    # =========================================================================
    # DATA PROCESSING AND DISPLAY METHODS
    # =========================================================================

    def _export_and_display_data(self) -> None:
        """Export data and display in table format."""
        logging.info(f"Fetched {len(self.rawdata)} raw records from API.")

        api_name = self.api_call.__name__
        DataExporter.export_with_processing(  # type: ignore[no-untyped-call]
            self.rawdata, self.filename, sort_key=self.sort_key, api_function_name=api_name
        )
        print(f"! {len(self.rawdata)} records exported to {self.filename}")

        self._display_table()

    def _display_table(self) -> None:
        """Prepare and display data in PrettyTable format."""
        data = self._prepare_data_for_display()
        fields = DataProcessingUtils.get_unique_keys(data)  # type: ignore[no-untyped-call]
        logging.debug(f"Unique fields for table: {fields}")

        table = self._build_pretty_table(data, fields)
        logging.debug("\n" + table.get_string())

    def _prepare_data_for_display(self) -> list[dict[str, Any]]:
        """Prepare raw data for table display."""
        data = [entry for entry in self.rawdata if isinstance(entry, dict)]

        if self.sort_key:
            sort_key_str: str = self.sort_key  # Type narrowing
            data = sorted(data, key=lambda x: x.get(sort_key_str, ""))

        data = DataProcessingUtils.flatten_nested_fields(data)
        data = DataProcessingUtils.escape_multiline(data)  # type: ignore[no-untyped-call]
        return data  # type: ignore[no-any-return]

    def _build_pretty_table(self, data: list[dict[str, Any]], fields: list[str]) -> Any:
        """Build PrettyTable from processed data."""
        table = PrettyTable()
        table.field_names = self.display_fields if self.display_fields else fields
        table.valign = "t"

        for item in tqdm(data, desc="Processing", unit="record"):  # type: ignore[no-untyped-call]
            row = [item.get(field, "") for field in table.field_names]
            table.add_row(row)

        return table


def execute_with_connection_pool_management(  # noqa: C901, PLR0912, PLR0915
    work_items: list[Any], worker_function: Any, batch_description: str = "items", retry_function: Any | None = None
) -> tuple[list[Any], list[Any]]:
    """
    Execute a list of work items using connection pool management and configurable threading.

    This is a reusable helper that any function can use to benefit from:
    - Connection-aware vs CPU-aware threading
    - Semaphore-based connection limiting
    - Configurable batch processing
    - Automatic retry handling
    - Progress tracking

    Args:
        work_items: List of items to process
        worker_function: Function to call for each item. Should accept (item, connection_semaphore) parameters
        batch_description: Description for progress tracking (e.g., "devices", "sites")
        retry_function: Optional function to call for retry logic.
            Should accept (failed_items, connection_semaphore) parameters

    Returns:
        Tuple of (successful_results, failed_items)
    """

    if not work_items:
        logging.info(f"* No {batch_description} to process.")
        return [], []

    logging.info(f"* Processing {len(work_items)} {batch_description} with connection pool management...")

    # Determine threading strategy from environment variables
    if FAST_MODE_USE_CONNECTION_AWARE_THREADING:
        # Connection-aware threading: limit threads to connection pool capacity
        max_threads = FAST_MODE_MAX_CONCURRENT_CONNECTIONS
        threading_mode = "connection-aware"
        logging.info(f"! Connection-aware threading: Using {max_threads} threads (respects connection pool limit)")
    else:
        # CPU-aware threading: use maximum CPU threads available
        max_threads = os.cpu_count() or FAST_MODE_FALLBACK_THREADS
        threading_mode = "CPU-aware"
        logging.info(f"! CPU-aware threading: Using {max_threads} threads (maximum CPU utilization)")

    # Create a semaphore to limit concurrent API connections
    connection_semaphore = threading.Semaphore(FAST_MODE_MAX_CONCURRENT_CONNECTIONS)
    logging.info(f"* Connection pool protection: Maximum {FAST_MODE_MAX_CONCURRENT_CONNECTIONS} concurrent API calls")

    # Calculate optimal batch size using configurable devices per thread
    devices_per_thread = FAST_MODE_DEVICES_PER_THREAD
    batch_size = max_threads * devices_per_thread
    successful_results = []
    failed_items = []

    # Process items in batches
    for batch_index in range(0, len(work_items), batch_size):
        try:
            batch = work_items[batch_index : batch_index + batch_size]
            batch_number = (batch_index // batch_size) + 1
            total_batches = (len(work_items) + batch_size - 1) // batch_size
            logging.info(
                f"! Processing batch {batch_number}/{total_batches} ({len(batch)} {batch_description}, ~{len(batch) / max_threads:.0f} per thread)"  # noqa: E501
            )
            with ThreadPoolExecutor(max_workers=max_threads) as executor:
                # Submit batch tasks with connection semaphore
                future_to_item = {executor.submit(worker_function, item, connection_semaphore): item for item in batch}
                batch_desc = f"Batch {batch_number}/{total_batches}"
                # Strategy: optionally avoid as_completed entirely using wait loop for stability
                use_wait_loop = True  # Default to True after repeated environment anomalies
                first_result_logged = False
                if use_wait_loop:
                    pending = set(future_to_item.keys())
                    pbar_total = len(pending)
                    # tqdm(total=...) is valid pattern for manual progress updates
                    with tqdm(total=pbar_total, desc=batch_desc, unit=batch_description.rstrip("s")) as pbar:  # type: ignore[call-arg, no-untyped-call]
                        while pending:
                            done, pending = wait(pending, return_when=FIRST_COMPLETED)
                            for future in done:
                                item = future_to_item[future]
                                try:
                                    result = future.result()
                                    if result:
                                        successful_results.append(result)
                                        if not first_result_logged:
                                            logging.debug(f"! First future result type: {type(result)}")
                                            first_result_logged = True
                                    else:
                                        failed_items.append(item)
                                except Exception as e:
                                    logging.error(f"! Future exception for {batch_description.rstrip('s')} {item}: {e}")
                                    failed_items.append(item)
                                finally:
                                    try:
                                        pbar.update(1)
                                    except Exception as upd_err:
                                        logging.error(f"! Progress bar update failed: {upd_err}")
                else:
                    # Retained fallback path (not expected to be used now)
                    for future in as_completed(future_to_item):
                        item = future_to_item[future]
                        try:
                            result = future.result()
                            if result:
                                successful_results.append(result)
                            else:
                                failed_items.append(item)
                        except Exception as e:
                            logging.error(f"! Future exception for {batch_description.rstrip('s')} {item}: {e}")
                            failed_items.append(item)
        except Exception as batch_exc:
            # Log detailed context about the batch to aid debugging (e.g., dict+float arithmetic errors outside futures)
            logging.error(f"! Batch-level exception in execute_with_connection_pool_management: {batch_exc}")
            logging.error(
                f"! Batch context: batch_index={batch_index}, batch_size={batch_size}, max_threads={max_threads}, threading_mode={threading_mode}"  # noqa: E501
            )
            try:
                import traceback as _tb2

                formatted = "".join(_tb2.format_exception(type(batch_exc), batch_exc, batch_exc.__traceback__))
                for line in formatted.rstrip().splitlines():
                    logging.error(line)
            except Exception as trace_log_err:
                logging.error(f"! Failed to log batch exception traceback: {trace_log_err}")
            # Re-raise to allow outer handlers / global excepthook to capture as well
            raise

    # Handle retries if retry function is provided
    if failed_items and retry_function:
        logging.info(f"! Retrying {len(failed_items)} failed {batch_description}...")
        retry_results, still_failed = retry_function(failed_items, connection_semaphore)
        successful_results.extend(retry_results)
        failed_items = still_failed

    logging.info(f"! Processed {len(successful_results)} {batch_description} successfully, {len(failed_items)} failed")
    return successful_results, failed_items


